                     if let Err(re) = child.unmap(vaddr) {
                         warn!(
                             "link_user_pages(): partial rollback unmap failed (vaddr={vaddr:?}, \
                              error={re:?})"
                         );
                     }
                     return Err(e);
                 }
             }
